// 2. Code: Validate Event — validate lead ID and idempotency/correlation fields
const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

if (payload && payload.type === 'Buffer' && Array.isArray(payload.data)) {
  try {
    payload = JSON.parse(Buffer.from(payload.data).toString('utf8'));
  } catch (e) {}
}

const eventData = payload.data || payload;
const leadId = eventData.leadId || payload.leadId || null;
const workflowRunId = eventData.workflowRunId || payload.workflowRunId || null;

if (!leadId) {
  throw new Error('Validation error: Missing leadId in RabbitMQ payload');
}

return [{
  json: {
    leadId,
    workflowRunId,
    eventData,
    rawEvent: payload
  }
}];

// 7. Code: Aggregate Features — build deterministic scoring features with documented weights and AI prompt
const eventMeta = $('Code: Validate Event').first().json;
const leadRes = $('HTTP Request: Get Lead').first().json;
const qualRes = $('HTTP Request: Get Latest Qualification').first().json;
const enrichRes = $('HTTP Request: Get Latest Enrichment').first().json;
const contextRes = $('HTTP Request: Get Interactions').first().json;

const lead = leadRes?.id ? leadRes : (eventMeta.eventData?.leadData || eventMeta.eventData?.lead || {});
const qual = qualRes?.status ? qualRes : (eventMeta.eventData?.qualificationData || eventMeta.eventData?.qualification || null);
const enrich = enrichRes?.id ? enrichRes : (eventMeta.eventData?.enrichmentData || eventMeta.eventData?.enrichment || null);
const interactions = Array.isArray(contextRes?.interactions) ? contextRes.interactions : (eventMeta.eventData?.interactions || []);

const leadId = eventMeta.leadId;
const workflowRunId = eventMeta.workflowRunId;

// Calculate deterministic scoring feature points
let profileFitPoints = 0;
const companySize = enrich?.companySize ?? lead.companySize;
if (typeof companySize === 'number') {
  if (companySize >= 100) profileFitPoints = 20;
  else if (companySize >= 20) profileFitPoints = 15;
  else if (companySize >= 5) profileFitPoints = 10;
  else profileFitPoints = 5;
} else if (lead.companyName || enrich?.companyName) {
  profileFitPoints = 10;
}

let decisionMakerPoints = 0;
const jobTitle = (enrich?.contactJobTitle || lead.jobTitle || '').toLowerCase();
const decisionKeywords = ['ceo', 'cto', 'cfo', 'coo', 'cmo', 'cio', 'vp', 'director', 'founder', 'owner', 'head of', 'lead'];
if (decisionKeywords.some((kw) => jobTitle.includes(kw))) {
  decisionMakerPoints = 20;
} else if (jobTitle.length > 0) {
  decisionMakerPoints = 10;
}

let qualificationPoints = 0;
if (qual && qual.status === 'QUALIFIED') {
  const conf = typeof qual.confidence === 'number' ? qual.confidence : 0.85;
  qualificationPoints = Math.round(conf * 25);
} else if (qual && qual.status === 'DISQUALIFIED') {
  qualificationPoints = -20;
} else if (qual && qual.status === 'NEEDS_REVIEW') {
  qualificationPoints = 10;
}

const engagementPoints = Math.min(25, interactions.length * 8);
const enrichmentBonus = (enrich && enrich.status === 'SUCCESS') ? 10 : 0;

const scoringFeatures = {
  baseScore: 20,
  profileFitPoints,
  decisionMakerPoints,
  qualificationPoints,
  engagementPoints,
  enrichmentBonus
};

const fullName = `${lead.firstName || ''} ${lead.lastName || ''}`.trim() || 'Unknown';
const prompt = `
You are an enterprise AI Lead Scoring model. Evaluate and score the following prospective lead for sales readiness.

=== LEAD PROFILE ===
- Full Name: ${fullName}
- Email: ${lead.email || 'N/A'}
- Job Title: ${jobTitle || 'Unknown'}
- Company: ${enrich?.companyName || lead.companyName || 'Unknown'}
- Website: ${enrich?.companyWebsite || lead.companyWebsite || 'None'}
- Industry: ${enrich?.companyIndustry || lead.industry || 'Unknown'}
- Company Size: ${companySize ?? 'Unknown'}
- CRM Status: ${lead.status || 'NEW'}

=== AI QUALIFICATION ===
- Status: ${qual?.status || 'NOT_QUALIFIED'}
- Confidence: ${qual?.confidence != null ? Math.round(qual.confidence * 100) + '%' : 'N/A'}

=== ENRICHMENT ===
- Status: ${enrich?.status || 'NOT_ENRICHED'}

=== INTERACTIONS ===
- Total: ${interactions.length}

Respond ONLY in this exact JSON schema:
{
  "score": 85,
  "label": "HOT" | "WARM" | "COLD",
  "reason": "Detailed explanation for this score based on profile fit and decision maker title.",
  "scoringFeatures": ${JSON.stringify(scoringFeatures)}
}
`;

return [{
  json: {
    leadId,
    workflowRunId,
    lead,
    qual,
    enrich,
    interactions,
    scoringFeatures,
    prompt
  }
}];

// 9. Code: Validate Canonical Score — validate response shape, score boundaries, label and policy version
const response = $input.first().json;
const prep = $('Code: Aggregate Features').first().json;

const leadId = prep.leadId;
const workflowRunId = prep.workflowRunId;
const scoringFeatures = prep.scoringFeatures;

let geminiOutput = null;
try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    geminiOutput = JSON.parse(rawText);
  }
} catch (e) {
  geminiOutput = null;
}

let finalScore = 0;
let label = 'COLD';
let reason = '';
let modelInfo = {};

if (geminiOutput && typeof geminiOutput.score === 'number' && !isNaN(geminiOutput.score)) {
  finalScore = Math.max(0, Math.min(100, Math.round(geminiOutput.score)));
  label = finalScore >= 75 ? 'HOT' : finalScore >= 40 ? 'WARM' : 'COLD';
  reason = `[Gemini AI - ${label} ${finalScore}/100] ${geminiOutput.reason || 'AI evaluated lead profile.'}`;
  modelInfo = {
    provider: 'google',
    model: $env.GEMINI_MODEL || 'gemini-3.5-flash-lite',
    modelVersion: 'v1beta'
  };
} else {
  // Deterministic Fallback Policy
  const calculated = 20 +
    scoringFeatures.profileFitPoints +
    scoringFeatures.decisionMakerPoints +
    scoringFeatures.qualificationPoints +
    scoringFeatures.engagementPoints +
    scoringFeatures.enrichmentBonus;

  finalScore = Math.max(0, Math.min(100, Math.round(calculated)));
  label = finalScore >= 75 ? 'HOT' : finalScore >= 40 ? 'WARM' : 'COLD';
  reason = `[Canonical Policy - ${label} ${finalScore}/100] Evaluated from profile fit, decision authority, qualification, and activity.`;
  modelInfo = {
    provider: 'crm-scoring-policy',
    model: 'deterministic-scoring-v1',
    modelVersion: '1.0'
  };
}

return [{
  json: {
    leadId,
    workflowRunId,
    status: 'SUCCESS',
    score: finalScore,
    label,
    reason,
    scoringFeatures,
    modelInfo,
    evaluatedAt: new Date().toISOString()
  }
}];

